"""Kickoff 51 analysis, fixed before the data (section 3 of the kickoff; k51-rule.md).

Per M (144, then 143), from the counts of the 56 circuits:
- F_no(phi) and F_ref: the squared Hellinger overlap with the wait test's phi = 0 parity ideal (manacitra.wait), pooled
  over the two copies; the outcome keys in the repository's order (tests/_reuse_runs.py, _wait_test_keys).
- M's P(1) from its own bit (c5), pooled over the two copies; loss = P(1) - P(1) of Z.
- d(phi) = F_no(phi) - F_ref (1 - loss_R0(phi)); the swing A = [d(+90) - d(-90)] / 2. Beside: d1 and A1 with R1, d2 and
  A2 with R2; the mean |d1| and mean |d0| over the three phi; the 3-point fits of loss_R0(phi) and loss_R2(phi) to
  a sin^2((phi + theta) / 2) + b (exact through three points, a >= 0; labelled as fits); d(0), Kickoff 50's d0.
- 90% intervals (5th and 95th percentiles) from one joint bootstrap, seed 51, 10,000 draws, in a fixed order: M by M;
  F for W-no at -90, 0, +90, then W-ref (copies with replacement, each redrawn from a multinomial); then P(1) for Z,
  R0 at -90, 0, +90, R1 likewise, R2 likewise (copies with replacement, each redrawn binomially).

H51: SUPPORTED if A's interval lies entirely outside [-0.05, +0.05] on at least one of the two qubits; NOT SUPPORTED if
A's interval lies entirely inside [-0.03, +0.03] on both; NOT SETTLED otherwise.

Usage: python analyse_51.py                 (Kickoff 51's files)
       python analyse_51.py --synthetic     (counts drawn from stated swings, to exercise the code before the data)"""
from __future__ import annotations

import hashlib
import json
import math
import sys
import time
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE / "site"))
sys.path.insert(0, str(HERE / "src-a55354d" / "tests"))
from manacitra import wait as W  # noqa: E402
import _reuse_runs as reuse  # noqa: E402

ORDER_M = ("144", "143")
PHIS = (-90, 0, 90)
SEED, N_BOOT = 51, 10_000
OUTSIDE, INSIDE = 0.05, 0.03
CAL_K50_UTC = datetime(2026, 10, 13, 17, 32, 21, tzinfo=timezone.utc)
K50_D0 = {"144": 0.044, "143": -0.014}


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


pct = reuse.pct


def fit3(lm, l0, lp):
    """loss(phi) = a sin^2((phi + theta)/2) + b through the points at -90, 0, +90 degrees, a >= 0: theta in degrees."""
    c = (lp + lm) / 2
    ks, kc = (lp - lm) / 2, c - l0
    k = np.hypot(ks, kc)
    return {"theta_deg": np.degrees(np.arctan2(ks, kc)), "a": 2 * k, "b": c - k}


def analyse(labels, counts):
    keys, q = reuse._wait_test_keys()

    def F(V):
        return np.sqrt(V / V.sum(-1, keepdims=True) * q).sum(-1) ** 2

    cells, bits = defaultdict(list), defaultdict(list)
    for lab, cts in zip(labels, counts):
        key = (str(lab["M"]), lab["circuit"], lab["phi_deg"])
        if lab["part"] == "W":
            d = defaultdict(int)
            for k, n in cts.items():
                d[k.replace(" ", "")[-W.WAIT_TEST_CLBITS:]] += n
            cells[key].append((lab["copy"], [d.get(k, 0) for k in keys]))
        else:
            i = lab["m_clbit"]
            ones = sum(n for k, n in cts.items() if k.replace(" ", "")[::-1][i] == "1")
            bits[key].append((lab["copy"], ones, sum(cts.values())))
    for dd in (cells, bits):
        for k in dd:
            dd[k].sort(key=lambda x: x[0])

    rng = np.random.default_rng(SEED)

    def draw_F(key):
        V = np.array([x[1] for x in cells[key]], float)
        freq = V / V.sum(1, keepdims=True)
        idx = rng.integers(0, V.shape[0], size=(N_BOOT, V.shape[0]))
        return F(rng.multinomial(int(V[0].sum()), freq[idx]).sum(1))

    def draw_P(key):
        o = np.array([x[1] for x in bits[key]])
        t = np.array([x[2] for x in bits[key]])
        acc1, accn = np.zeros(N_BOOT), np.zeros(N_BOOT)
        for _ in range(len(o)):
            pick = rng.integers(0, len(o), size=N_BOOT)
            acc1 += rng.binomial(t[pick], o[pick] / t[pick])
            accn += t[pick]
        return acc1 / accn

    ideal = W.wait_test_ideal()
    out = {}
    for M in ORDER_M:
        wkeys = [(M, "W-no", p) for p in PHIS] + [(M, "W-ref", 0)]
        rkeys = [(M, "Z", 0)] + [(M, k, p) for k in ("R0", "R1", "R2") for p in PHIS]
        Fb = {k: draw_F(k) for k in wkeys}
        Pb = {k: draw_P(k) for k in rkeys}
        Fp = {}
        for k in wkeys:
            pooled = defaultdict(int)
            for lab, cts in zip(labels, counts):
                if (str(lab["M"]), lab["circuit"], lab["phi_deg"]) == k:
                    for kk, n in cts.items():
                        pooled[kk.replace(" ", "")[-W.WAIT_TEST_CLBITS:]] += n
            Fp[k] = W.fidelity(dict(pooled), ideal)
        P = {k: sum(x[1] for x in bits[k]) / sum(x[2] for x in bits[k]) for k in rkeys}
        z = (M, "Z", 0)
        loss = {(c, p): P[(M, c, p)] - P[z] for c in ("R0", "R1", "R2") for p in PHIS}
        loss_b = {(c, p): Pb[(M, c, p)] - Pb[z] for c in ("R0", "R1", "R2") for p in PHIS}
        f_ref, f_ref_b = Fp[(M, "W-ref", 0)], Fb[(M, "W-ref", 0)]
        res = {"F_no": {p: Fp[(M, "W-no", p)] for p in PHIS}, "F_no_ci90": {p: pct(Fb[(M, "W-no", p)]) for p in PHIS},
               "F_ref": f_ref, "F_ref_ci90": pct(f_ref_b), "P1_Z": P[z], "P1_Z_ci90": pct(Pb[z]),
               "loss": {f"{c}|{p:+d}": v for (c, p), v in loss.items()}, "loss_ci90": {f"{c}|{p:+d}": pct(v) for (c, p), v in loss_b.items()}}
        for tag, c in (("", "R0"), ("1", "R1"), ("2", "R2")):
            d = {p: Fp[(M, "W-no", p)] - f_ref * (1 - loss[(c, p)]) for p in PHIS}
            db = {p: Fb[(M, "W-no", p)] - f_ref_b * (1 - loss_b[(c, p)]) for p in PHIS}
            res[f"d{tag or '0'}"] = d
            res[f"d{tag or '0'}_ci90"] = {p: pct(db[p]) for p in PHIS}
            res[f"A{tag}"] = (d[90] - d[-90]) / 2
            res[f"A{tag}_ci90"] = pct((db[90] - db[-90]) / 2)
            res[f"mean_abs_d{tag or '0'}"] = float(np.mean([abs(d[p]) for p in PHIS]))
        for c in ("R0", "R2"):
            f = fit3(*(loss[(c, p)] for p in PHIS))
            fb = fit3(*(loss_b[(c, p)] for p in PHIS))
            th = f["theta_deg"]
            wrapped = th + (fb["theta_deg"] - th + 180) % 360 - 180
            res[f"fit_{c}"] = {"theta_deg": float(th), "theta_ci90": pct(wrapped), "a": float(f["a"]), "b": float(f["b"]),
                               "label": "a fit (exact through the three points), not a measurement"}
        res["R1_tracks_better_than_R0"] = res["mean_abs_d1"] < res["mean_abs_d0"]
        lo, hi = res["A_ci90"]
        res["A_outside_0p05"] = lo > OUTSIDE or hi < -OUTSIDE
        res["A_inside_0p03"] = lo > -INSIDE and hi < INSIDE
        out[M] = res
    if any(out[M]["A_outside_0p05"] for M in ORDER_M):
        verdict = "SUPPORTED"
    elif all(out[M]["A_inside_0p03"] for M in ORDER_M):
        verdict = "NOT SUPPORTED"
    else:
        verdict = "NOT SETTLED"
    return {"verdict": verdict, "per_M": out}


def synthetic():
    """Counts drawn from stated distributions through the same code. M's Ramsey P(1) = 0.01 + sin^2((phi + theta_R)/2);
    the wait test's F_no(phi) = F_ref cos^2((phi + theta_W)/2). Case 1: theta_W = theta_R on both (no swing; expect NOT
    SUPPORTED). Case 2: theta_W = theta_R - 30 degrees on 144 (a swing; expect SUPPORTED)."""
    ideal = W.wait_test_ideal()
    ik = sorted(ideal)
    rng = np.random.default_rng(7)

    def w_counts(f):
        p = {k: f / 32 for k in ik}
        p["000001"] = 1 - f
        ks = list(p)
        n = rng.multinomial(5000, [p[k] for k in ks])
        return {k: int(v) for k, v in zip(ks, n) if v}

    def r_counts(p1):
        o = int(rng.binomial(5000, min(max(p1, 0), 1)))
        return {"000000": 5000 - o, "100000": o}

    s2 = lambda x: math.sin(math.radians(x) / 2) ** 2
    c2 = lambda x: math.cos(math.radians(x) / 2) ** 2
    for case, shift in ((1, {"144": 0, "143": 0}), (2, {"144": -30, "143": 0})):
        labels, counts = [], []
        for M, (thR, fref) in (("144", (25, 0.9)), ("143", (95, 0.92))):
            thW = thR + shift[M]
            for cp in (1, 2):
                for p in PHIS:
                    labels.append({"M": int(M), "part": "W", "circuit": "W-no", "phi_deg": p, "copy": cp}); counts.append(w_counts(fref * c2(p + thW)))
                labels.append({"M": int(M), "part": "W", "circuit": "W-ref", "phi_deg": 0, "copy": cp}); counts.append(w_counts(fref))
                labels.append({"M": int(M), "part": "R", "circuit": "Z", "phi_deg": 0, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.01))
                for c, extra in (("R0", 0), ("R1", 0), ("R2", 60)):
                    for p in PHIS:
                        labels.append({"M": int(M), "part": "R", "circuit": c, "phi_deg": p, "copy": cp, "m_clbit": 5})
                        counts.append(r_counts(0.01 + s2(p + thR + extra)))
        r = analyse(labels, counts)
        print("synthetic case", case, r["verdict"], {M: (round(r["per_M"][M]["A"], 3), [round(x, 3) for x in r["per_M"][M]["A_ci90"]],
                                                         round(r["per_M"][M]["fit_R0"]["theta_deg"], 1), round(r["per_M"][M]["fit_R2"]["theta_deg"], 1)) for M in ORDER_M})
